+package com.example.contact;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Application-wide record of every message sent, so the list survives
+ * navigation and is shared by all visits. Kept in memory only.
+ */
+@Service
+public class ContactMessageStore {
+
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public List<ContactMessage> findAllNewestFirst() {
+        return List.copyOf(messages);
+    }
+
+}
