+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL = Pattern.compile(EmailValidator.PATTERN);
+
+    private final ContactMessageStore store;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messageGrid = new Grid<>();
+
+    private final Dialog discardDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageStore store) {
+        this.store = store;
+
+        // Eager, so the value is up to date when Enter is pressed straight after typing
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(event -> send.setEnabled(true));
+        email.addValueChangeListener(event -> send.setEnabled(true));
+        phone.addValueChangeListener(event -> send.setEnabled(true));
+        message.addValueChangeListener(event -> send.setEnabled(true));
+
+        var form = new FormLayout();
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1), new FormLayout.ResponsiveStep("40em", 2));
+        form.add(name, email, phone, message);
+        form.setColspan(message, 2);
+        form.setWidthFull();
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> submit());
+        Shortcuts.addShortcutListener(this, this::submit, Key.ENTER);
+
+        messageGrid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        messageGrid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        messageGrid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        messageGrid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        messageGrid.setItems(store.findAllNewestFirst());
+        messageGrid.setWidthFull();
+
+        discardDialog.setHeaderTitle("Discard your message?");
+        discardDialog.add("You have typed a message that has not been sent. Leaving now throws it away.");
+        var keepEditing = new Button("Keep editing", event -> keepEditing());
+        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        var discard = new Button("Discard", event -> discard());
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        discardDialog.getFooter().add(keepEditing, discard);
+        // Esc or a click outside the dialog also means keep editing
+        discardDialog.addDialogCloseActionListener(event -> keepEditing());
+
+        setAlignItems(FlexComponent.Alignment.START);
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, messageGrid, discardDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasTypedInput()) {
+            pendingNavigation = event.postpone();
+            discardDialog.open();
+        }
+    }
+
+    private boolean hasTypedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void keepEditing() {
+        // Cancelling (not just dropping the action) lets the client know the navigation is over
+        if (pendingNavigation != null) {
+            pendingNavigation.cancel();
+            pendingNavigation = null;
+        }
+        discardDialog.close();
+    }
+
+    private void discard() {
+        discardDialog.close();
+        pendingNavigation.proceed();
+    }
+
+    private void submit() {
+        // Enter reaches the view even while the leave prompt is open, so ignore it there
+        if (!send.isEnabled() || discardDialog.isOpened()) {
+            return;
+        }
+
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        var nameValue = name.getValue().trim();
+        var emailValue = email.getValue().trim();
+        var phoneValue = phone.getValue().trim();
+        var messageValue = message.getValue().trim();
+
+        // Every failing rule marks its field; the e-mail and phone rules are mutually exclusive
+        boolean valid = true;
+        if (nameValue.isEmpty()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (messageValue.isEmpty()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.codePointCount(0, messageValue.length()) > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+        if (!valid) {
+            return;
+        }
+
+        store.add(new ContactMessage(nameValue, emailValue, phoneValue, messageValue));
+        clearForm();
+        // Clearing the fields fires the edit listeners, so disable Send only after it
+        send.setEnabled(false);
+        messageGrid.setItems(store.findAllNewestFirst());
+        Notification.show("Message sent");
+    }
+
+    private void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearForm() {
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+    }
+
+}
