+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.springframework.test.annotation.DirtiesContext;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void emptySendShowsErrorsAndSendsNothing() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+        assertThat(page.locator("vaadin-notification-card")).hasCount(0);
+    }
+
+    @Test
+    void enterKeySendsAndClearsTheForm() {
+        field("Name").fill("Browser Alice");
+        field("Phone").fill("555-0199");
+        field("Message").fill("Sent from a real browser");
+
+        field("Phone").press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(firstRowCell()).hasText("Browser Alice");
+        assertThat(field("Name")).hasValue("");
+        assertThat(field("Message")).hasValue("");
+        assertThat(ButtonElement.getByText(page, "Send").getLocator()).isDisabled();
+    }
+
+    @Test
+    void enterInTheMessageSendsButShiftEnterStartsANewLine() {
+        field("Name").fill("Line Writer");
+        field("Phone").fill("555-0198");
+        field("Message").fill("first line");
+        field("Message").press("Shift+Enter");
+
+        assertThat(field("Message")).hasValue("first line\n");
+        assertThat(page.locator("vaadin-notification-card")).hasCount(0);
+
+        field("Message").pressSequentially("second line");
+        field("Message").press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(firstRowCell()).hasText("Line Writer");
+    }
+
+    @Test
+    void sendIsEnabledAgainAfterEditing() {
+        field("Name").fill("Editor");
+        field("Phone").fill("555-0197");
+        field("Message").fill("Edit me");
+        ButtonElement.getByText(page, "Send").click();
+        assertThat(ButtonElement.getByText(page, "Send").getLocator()).isDisabled();
+
+        field("Phone").fill("555-0196");
+
+        assertThat(ButtonElement.getByText(page, "Send").getLocator()).isEnabled();
+    }
+
+    @Test
+    void leavingWithTypedTextAsksBeforeNavigating() {
+        field("Name").fill("Half Written");
+        var dialog = new DialogElement(page);
+
+        aboutLink().click();
+        dialog.assertOpen();
+        dialog.assertHeaderText("Discard your message?");
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        dialog.assertClosed();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(field("Name")).hasValue("Half Written");
+
+        // Asking again still works after Keep editing, and after the dialog was dismissed with Esc
+        aboutLink().click();
+        dialog.assertOpen();
+        dialog.closeWithEscape();
+        dialog.assertClosed();
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        aboutLink().click();
+        dialog.assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void enterWhileTheLeaveDialogIsOpenDoesNotSend() {
+        field("Name").fill("Dialog Enter");
+        field("Phone").fill("555-0194");
+        field("Message").fill("Must not be sent from behind the dialog");
+        aboutLink().click();
+        var dialog = new DialogElement(page);
+        dialog.assertOpen();
+
+        page.keyboard().press("Enter");
+        // Events reach the server in order, so once Keep editing has been handled the Enter has been too
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+
+        dialog.assertClosed();
+        assertThat(field("Message")).hasValue("Must not be sent from behind the dialog");
+        assertThat(page.locator("vaadin-notification-card")).hasCount(0);
+    }
+
+    @Test
+    void leavingWithEmptyFormIsNotInterrupted() {
+        aboutLink().click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        new DialogElement(page).assertClosed();
+    }
+
+    @Test
+    void messagesSurviveANewVisit() {
+        field("Name").fill("Remembered Visitor");
+        field("Phone").fill("555-0195");
+        field("Message").fill("Still here next visit");
+        ButtonElement.getByText(page, "Send").click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        page.navigate(getUrl() + getView());
+
+        assertThat(page.getByText("Remembered Visitor")).isVisible();
+    }
+
+    private Locator firstRowCell() {
+        return GridElement.get(page).findRow(0).orElseThrow().getCell(0).getCellContentLocator();
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private Locator field(String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+}
