+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+// The sent messages live in an application-wide store, so the context is not shared with other test classes
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingAboutLinkAndEnabledEmptyForm() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(find(RouterLink.class).withText("About").exists());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptyFormMarksEveryRequiredFieldAndSendsNothing() {
+        navigate(ContactView.class);
+        int before = sentCount();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertEquals(before, sentCount());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void whitespaceOnlyNameAndMessageAreBlank() {
+        navigate(ContactView.class);
+        test(name()).setValue("   ");
+        test(phone()).setValue("555-0100");
+        test(message()).setValue("  ");
+
+        test(send()).click();
+
+        assertEquals("Name is required", name().getErrorMessage());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(email().isInvalid());
+    }
+
+    @Test
+    void malformedEmailIsRejectedButNotRequiredWhenPhoneIsGiven() {
+        navigate(ContactView.class);
+        test(name()).setValue("Alice");
+        test(email()).setValue("not-an-email");
+        test(message()).setValue("Hello");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnough() {
+        navigate(ContactView.class);
+        var before = sentCount();
+        test(name()).setValue("Phone Only");
+        test(phone()).setValue("555-0101");
+        test(message()).setValue("Call me back");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(before + 1, sentCount());
+        assertEquals("Phone Only", firstSentRow().name());
+        assertEquals("555-0101", firstSentRow().phone());
+    }
+
+    @Test
+    void emailAddressAloneIsEnough() {
+        navigate(ContactView.class);
+        test(name()).setValue("Email Only");
+        test(email()).setValue("someone@example.com");
+        test(message()).setValue("Write to me");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals("someone@example.com", firstSentRow().email());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Too Long");
+        test(email()).setValue("long@example.com");
+        test(message()).setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void messageOf500CharactersIsAccepted() {
+        navigate(ContactView.class);
+        test(name()).setValue("Just Fits");
+        test(email()).setValue("fits@example.com");
+        test(message()).setValue("x".repeat(500));
+
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals("Just Fits", firstSentRow().name());
+    }
+
+    @Test
+    void sendingShowsNotificationAddsRowAndClearsForm() {
+        navigate(ContactView.class);
+        var before = sentCount();
+        fillValidForm("Sender One", "one@example.com", "Hello one");
+
+        test(send()).click();
+
+        assertEquals(before + 1, sentCount());
+        assertEquals("Hello one", firstSentRow().message());
+        assertEquals("Message sent", test(find(Notification.class).single()).getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void enterKeySendsAValidMessage() {
+        navigate(ContactView.class);
+        var before = sentCount();
+        fillValidForm("Enter Sender", "enter@example.com", "Sent with enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before + 1, sentCount());
+        assertEquals("Sent with enter", firstSentRow().message());
+    }
+
+    @Test
+    void enterKeyDoesNotSendAnInvalidMessage() {
+        navigate(ContactView.class);
+        var before = sentCount();
+        test(name()).setValue("No Message");
+        test(phone()).setValue("555-0102");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before, sentCount());
+        assertEquals("Message is required", message().getErrorMessage());
+    }
+
+    @Test
+    void sendIsEnabledAgainAfterAnyEdit() {
+        navigate(ContactView.class);
+        fillValidForm("Editor", "editor@example.com", "Edited later");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        test(phone()).setValue("555-0103");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void newestMessageIsFirstAndListSurvivesRevisiting() {
+        navigate(ContactView.class);
+        fillValidForm("First Visitor", "first@example.com", "Older message");
+        test(send()).click();
+        fillValidForm("Second Visitor", "second@example.com", "Newer message");
+        test(send()).click();
+
+        followAboutLink();
+        navigate(ContactView.class);
+
+        assertEquals("Second Visitor", firstSentRow().name());
+        assertEquals("First Visitor", sentRow(1).name());
+    }
+
+    @Test
+    void leavingWithEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        followAboutLink();
+
+        assertEquals("About", find(H1.class).single().getText());
+        assertFalse(find(Dialog.class).exists());
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirstAndKeepEditingStaysOnView() {
+        navigate(ContactView.class);
+        test(name()).setValue("Half Written");
+
+        followAboutLink();
+
+        var dialog = find(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertTrue(find(H1.class).withText("Contact").exists());
+
+        find(Button.class).withText("Keep editing").single().click();
+
+        assertFalse(dialog.isOpened());
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("Half Written", name().getValue());
+    }
+
+    @Test
+    void discardingNavigatesToAbout() {
+        navigate(ContactView.class);
+        test(message()).setValue("Not worth keeping");
+
+        followAboutLink();
+        find(Button.class).withText("Discard").single().click();
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    private void followAboutLink() {
+        test(find(RouterLink.class).withText("About").single()).click();
+    }
+
+    private void fillValidForm(String nameValue, String emailValue, String messageValue) {
+        test(name()).setValue(nameValue);
+        test(email()).setValue(emailValue);
+        test(message()).setValue(messageValue);
+    }
+
+    private int sentCount() {
+        return sentMessages().size();
+    }
+
+    private ContactMessage firstSentRow() {
+        return sentRow(0);
+    }
+
+    private ContactMessage sentRow(int index) {
+        return sentMessages().get(index);
+    }
+
+    private List<ContactMessage> sentMessages() {
+        return sentGrid().getListDataView().getItems().toList();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> sentGrid() {
+        return (Grid<ContactMessage>) find(Grid.class).single();
+    }
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+}
